// ---- n8n Code node – “Set Yesterday Range” ----
const now = new Date();

// ---- start of yesterday (00:00:00.000) ----
const start = new Date(
  now.getFullYear(),
  now.getMonth(),
  now.getDate() - 1,   // yesterday
  0, 0, 0, 0
);

// ---- end of yesterday (23:59:59.999) ----
const end = new Date(start);
end.setHours(23, 59, 59, 999);

return [
  {
    json: {
      startTs: start.getTime(),
      endTs:   end.getTime(),
    },
  },
];

const items = $input.all();

function extractEmail(c) {
  return (
    c.email?.value ||
    c.email ||
    c.contact_email ||
    c.person_email ||
    c.personal_email ||
    c.personal_emails?.[0]?.email ||
    c.work_email ||
    c.emails?.[0]?.email ||
    "" // fallback
  ).trim();
}

function extractPhone(c) {
  return (
    c.phone ||
    c.phone?.value ||
    c.phone_numbers?.[0]?.number ||
    c.mobile_numbers?.[0]?.number ||
    c.work_phone ||
    c.direct_phone ||
    ""
  ).trim();
}

return items.map(i => {
  const c = i.json;

  return {
    json: {
      //------------------------------------------------------------
      // Normalized core fields (KEEP EXACTLY AS YOU HAD)
      //------------------------------------------------------------
      first_name: c.first_name?.value || c.first_name || c.properties?.firstname || "",
      last_name: c.last_name?.value || c.last_name || c.properties?.lastname || "",
      email: extractEmail(c),
      title: c.title || c.properties?.jobtitle || "",
      company_name: c.company?.name || c.company_name || "",
      linkedin_url: c.linkedin_url || c["LinkedIn Profile"] || "",
      seniority: c.seniority || "",
      phone: extractPhone(c),

      //------------------------------------------------------------
      // 🔥 CRITICAL FIX — PRESERVE CONTACT → COMPANY RELATIONSHIP
      //------------------------------------------------------------
      company_id: c.company_id || c.company?.id || "",
      company: c.company || "",

      //------------------------------------------------------------
      // 🔥 CRITICAL FIX — PRESERVE OWNER ASSIGNMENT THROUGH FLOW
      //------------------------------------------------------------
      hubspot_owner_id: c.hubspot_owner_id,
      assigned_owner_name: c.assigned_owner_name,
      assigned_owner_email: c.assigned_owner_email,
      territory: c.territory,

      //------------------------------------------------------------
      // Keep full raw object for debugging
      //------------------------------------------------------------
      _raw: c
    }
  };
});

//------------------------------------------------------------
// Filter out ANY contact that does not have a valid email
// This prevents HubSpot INVALID_EMAIL 400 errors
//------------------------------------------------------------
const items = $input.all();

function norm(v) {
  if (!v) return "";
  if (typeof v === "string") return v.trim();
  if (v.value) return v.value.toString().trim();
  return "";
}

const out = [];

for (const i of items) {
  const c = i.json;
  const email = norm(c.email);

  // Skip if missing or invalid
  if (!email || !email.includes("@")) {
    continue;
  }

  // Keep only valid-email contacts
  out.push({
    json: {
      ...c,
      email,
    }
  });
}

return out;

// n8n Code node (Execute Once for All Items) - Normalize LinkedIn URLs
const items = $input.all();        // Accept all input items
const output = [];

// Helper function to normalize a raw LinkedIn URL value (handles string, object, or array)
function normalizeLinkedIn(raw) {
  if (raw == null) return "";
  let url = raw;
  // Unwrap value if it's an array or object (e.g., { value: "...", url: "..." } or ["..."])
  let attempts = 0;
  while (attempts < 5 && (Array.isArray(url) || (url && typeof url === "object"))) {
    if (Array.isArray(url)) {
      url = url.length ? url[0] : "";
    } else if (url && typeof url === "object") {
      url = url.url || url.value || "";
    }
    attempts++;
  }
  if (typeof url !== "string") return "";
  // Trim whitespace
  let cleaned = url.trim();
  if (!cleaned) return "";
  // Ensure the URL has "https://" prefix (force HTTPS)
  if (!/^https?:\/\//i.test(cleaned)) {
    cleaned = "https://" + cleaned;
  } else {
    cleaned = cleaned.replace(/^http:\/\//i, "https://");
  }
  // Remove any subdomain (e.g., "www.") for consistency
  cleaned = cleaned.replace(/:\/\/[^\/]*linkedin\.com\//i, "://linkedin.com/");
  // Strip query params or fragments (remove tracking tags like ?trk= etc.)
  cleaned = cleaned.split("?")[0].split("#")[0];
  // Only accept personal profile URLs containing "/in/"
  const match = cleaned.match(/linkedin\.com\/in\/([^\/\?\#]+)/i);
  if (!match) return "";
  const username = match[1];
  // Construct normalized profile URL with trailing slash
  return `https://linkedin.com/in/${username}/`;
}

// Process each contact item
for (const item of items) {
  const c = item.json;
  // Try multiple possible LinkedIn fields in order
  const fields = ["linkedin_url", "LinkedIn Profile", "linkedin", "linkedin_profile", "person_linkedin"];
  let normalizedLink = "";
  for (const field of fields) {
    if (c[field]) {
      normalizedLink = normalizeLinkedIn(c[field]);
      if (normalizedLink) break;  // stop when a valid link is found
    }
  }
  if (!normalizedLink) {
    // Skip this item if no valid LinkedIn URL was found
    continue;
  }
  // Build output item with original fields and the normalized linkedin_url
  const newJson = { ...c, linkedin_url: normalizedLink };
  // (Optional) Remove other LinkedIn fields to avoid duplicates, keeping only normalized linkedin_url
  for (const field of fields) {
    if (field !== "linkedin_url" && newJson[field] !== undefined) {
      delete newJson[field];
    }
  }
  // Add to output array in n8n format (each item as an object with a 'json' property)
  output.push({ json: newJson });
}

return output;

//------------------------------------------------------------
// Attach company owner to each contact using a lookup table
// Company → owner table is taken from node "Edit Fields1"
// (1 row per company with company_id + owner fields)
//------------------------------------------------------------

const contacts = $input.all();

// 1) Get all company-owner rows from your earlier node
//    ⚠️ Make sure this node name matches the one in your workflow
const companyItems = $items("Edit Fields1", 0, 0) || [];

// 2) Build lookup: company_id → { owner info }
const companyMap = {};
for (const item of companyItems) {
  const c = item.json || {};
  const id = c.company_id;
  if (!id) continue;

  companyMap[id] = {
    hubspot_owner_id: c.hubspot_owner_id,
    assigned_owner_name: c.assigned_owner_name,
    assigned_owner_email: c.assigned_owner_email,
    territory: c.territory,
  };
}

// 3) For each contact, attach the matching owner (if any)
const out = [];

for (const item of contacts) {
  const c = item.json || {};
  const id = c.company_id;

  const owner = id ? companyMap[id] : null;

  out.push({
    json: {
      ...c,
      // keep existing owner fields if already set, otherwise pull from table
      hubspot_owner_id: c.hubspot_owner_id ?? owner?.hubspot_owner_id ?? null,
      assigned_owner_name: c.assigned_owner_name ?? owner?.assigned_owner_name ?? null,
      assigned_owner_email: c.assigned_owner_email ?? owner?.assigned_owner_email ?? null,
      territory: c.territory ?? owner?.territory ?? null,
    },
  });
}

return out;

