//------------------------------------------------------------
// FILTER OUT contacts without a valid linkedin.com/in/ URL
// Guarantees Amplemarket never receives undefined or invalid URLs
//------------------------------------------------------------
const items = $input.all();

function extractLinkedIn(c) {
  const possible = [
    c.linkedin_url,
    c["LinkedIn Profile"],
    c.linkedin,
    c.person_linkedin,
    c.linkedin_profile,
    c.linkedin_url?.value,
  ];

  for (const v of possible) {
    if (!v) continue;
    const url = v.toString().trim();
    if (url.startsWith("http") && url.includes("linkedin.com/")) {
      return url;
    }
  }

  return "";
}

const output = [];

for (const i of items) {
  const c = i.json;
  const linkedin = extractLinkedIn(c);

  // Skip if missing LinkedIn
  if (!linkedin) continue;

  output.push({
    json: {
      ...c,
      linkedin_url: linkedin,  // normalized LinkedIn URL
    },
  });
}

return output;

//------------------------------------------------------------
// Build Amplemarket "find by LinkedIn" URL for each contact
// Only keeps contacts with a valid person LinkedIn URL
//------------------------------------------------------------
const items = $input.all();
const out = [];

function cleanLinkedIn(url) {
  if (!url) return "";

  // Trim & strip tracking params
  url = url.trim().split("?")[0];

  // Must be a person profile, not company
  if (!url.includes("linkedin.com/in/")) return "";

  // Ensure trailing slash
  if (!url.endsWith("/")) url += "/";

  return url;
}

for (const item of items) {
  const c = item.json;

  // Try multiple possible fields, then fall back
  const rawUrl =
    c.linkedin_url ||
    c["LinkedIn Profile"] ||
    c.linkedin ||
    c.linkedin_profile ||
    "";

  const li = cleanLinkedIn(rawUrl);
  if (!li) {
    // No valid LinkedIn → skip this contact (don't send to Amplemarket)
    continue;
  }

  const ampleUrl =
    "https://api.amplemarket.com/people/find" +
    "?linkedin_url=" +
    encodeURIComponent(li) +
    "&reveal_email=true&reveal_phone_numbers=true";

  out.push({
    json: {
      ...c,
      linkedin_url: li,   // normalized
      ample_url: ampleUrl // used by HTTP Request node
    },
  });
}

return out;
